Sure, I'd be happy to help you create a to-do list that allows users to add and remove tasks. Here's a Python solution using a list data structure to store the tasks:

```python
# Initialize an empty to-do list
to_do_list = []

def add_task():
    """Add a new task to the to-do list."""
    user_input = input("Enter a task to add to your to-do list (or type 'done' to complete a task): ")

    # Add the task to the list if it's not 'done'
    if user_input.lower() != "done":
        to_do_list.append(user_input)
        print(f"Added {user_input} to your to-do list.")
    else:
        print("Task completed. You can add another task now.")

def remove_task():
    """Remove a task from the to-do list by index."""
    if to_do_list:
        index = int(input("Enter the index of the task to remove (0-based): "))
        if index < len(to_do_list):
            del to_do_list[index]
            print(f"Removed task at index {index}.")
        else:
            print("Index out of range. Please try again.")
    else:
        print("Your to-do list is empty. Add some tasks first.")

def print_to_do_list():
    """Print the current to-do list."""
    if to_do_list:
        print("Here's your to-do list:")
        for i, task in enumerate(to_do_list, start=1):
            print(f"{i}. {task}")
    else:
        print("Your to-do list is empty.")

# Main loop
while True:
    print("What would you like to do?")
    print("1. Add a task")
    print("2. Remove a task")
    print("3. Print to-do list")
    print("4. Exit")

    choice = int(input("Enter your choice: "))

    if choice == 1:
        add_task()
    elif choice == 2:
        remove_task()
    elif choice == 3:
        print_to_do_list()
    elif choice == 4:
        print("Goodbye!")
        break
    else:
        print("Invalid choice. Please try again.")
```

This script allows users to add tasks, remove tasks by index, and print the current to-do list. The user can also type 'done' to complete a task.
